<?php

declare(strict_types=1);

namespace Infomaniak\Ticketing;

/**
 * Infomaniak credentials used to authenticate API requests.
 *
 * - The API token is a Manager token (Bearer) scoped to the ticketing product.
 * - The API key is the key generated by the ticketing product itself (Shop / Online publishing > API access).
 */
final class Credentials
{
    public function __construct(
        private string $apiToken,
        private string $apiKey,
    ) {}

    public function apiToken(): string
    {
        return $this->apiToken;
    }

    public function apiKey(): string
    {
        return $this->apiKey;
    }
}
